import json
P = {"National":"NAT","Labour":"LAB","Green":"GRN","ACT":"ACT","NZ First":"NZF","Te Pāti Māori":"TPM","Opportunity":"OPP","Te Tai Tokerau":"OTH"}
def C(s):
    # "Party|Name|weight"
    parts=s.split("|"); pl=parts[0]; nm=parts[1]; w=int(parts[2]) if len(parts)>2 else 0
    code=P.get(pl,"MIN")
    if nm=="Tākuta Ferris": code="OTH"
    return {"p":code,"pl":pl,"nm":nm,"w":w}
S=[]
def seat(n,held,note,cands,m=False):
    S.append({"n":n,"held":held,"note":note,"m":m,"c":[C(x) for x in cands]})
